INSERT INTO `therapy_recommendations` VALUES (1,'2026-05-07 20:22:28.056','2026-05-15 12:35:11.341',NULL,2,16,'Admin merekomendasikan: Istirahat total selama 3 hari dan konsultasi psikolog. Jaga pola tidur dan kurangi beban kerja.','completed','general','medium','1_week',NULL,NULL,NULL),(2,'2026-05-07 20:23:35.244','2026-05-15 12:35:15.643',NULL,2,16,'halo gnatenf','completed','general','medium','1_week',NULL,NULL,NULL),(3,'2026-05-07 20:23:53.131','2026-05-15 12:35:18.881',NULL,2,16,'aloooo','completed','general','medium','1_week',NULL,NULL,NULL),(4,'2026-05-07 20:27:14.821','2026-05-15 12:35:21.504',NULL,2,16,'pp','completed','general','medium','1_week',NULL,NULL,NULL),(5,'2026-05-07 20:27:27.964','2026-05-15 12:35:25.015',NULL,2,16,'jahdiabsdjasfa','completed','general','medium','1_week',NULL,NULL,NULL),(6,'2026-05-07 20:27:48.250','2026-05-15 12:35:27.732',NULL,2,16,'aloooo','completed','general','medium','1_week',NULL,NULL,NULL),(7,'2026-05-07 20:28:00.569','2026-05-15 12:35:30.158',NULL,2,16,'Pertahankan kondisi saat ini. Tetap lakukan kuisioner harian untuk monitoring rutin.','completed','general','medium','1_week',NULL,NULL,NULL),(8,'2026-05-07 20:28:11.724','2026-05-15 11:23:40.859',NULL,2,16,'nafii makan','completed','general','medium','1_week',NULL,NULL,NULL),(9,'2026-05-07 20:28:19.033','2026-05-15 11:23:37.945',NULL,2,16,'a','completed','general','medium','1_week',NULL,NULL,NULL),(10,'2026-05-13 15:10:37.926','2026-05-15 11:23:35.105',NULL,2,18,'Sarankan mengikuti program manajemen stres. Pantau perkembangan melalui kuisioner harian.','completed','general','medium','1_week',NULL,NULL,NULL),(11,'2026-05-13 15:28:19.549','2026-05-13 17:12:08.201',NULL,2,18,'PROGRAM PREVENTIF: 1) Lanjutkan kuisioner pemantauan harian. 2) Pertahankan rutinitas olahraga ringan. 3) Praktikkan teknik pernapasan 5 menit/hari. 4) Ikuti sesi grup bulanan. 5) Tetap terhubung dengan support system.','completed','general','medium','1_week',NULL,NULL,NULL),(12,'2026-06-03 11:57:59.683','2026-08-13 15:20:00.979',NULL,2,27,'PROGRAM PREVENTIF: 1) Lanjutkan pemantauan harian. 2) Pertahankan rutinitas sehat. 3) Latihan napas 5 menit/hari. 4) Tetap terhubung dengan teman/keluarga. 5) Gunakan asesmen sebagai baseline.','completed','konseling','medium','1_week',NULL,NULL,NULL),(15,'2026-08-13 15:10:11.458','2026-08-13 15:10:11.458',NULL,16,29,'TINDAK LANJUT CURHAT AI (Tinggi)\nUser menyatakan keinginan bunuh diri secara eksplisit, dengan riwayat pernyataan serupa sebelumnya.\n\nSinyal terdeteksi:\n- Pernyataan eksplisit \'aku pengen bundir\'\n- Riwayat pernyataan bunuh diri berulang\n- Pernyataan \'beneran\' sebelumnya menegaskan keseriusan\n\nRencana tindakan:\n- Hubungi user melalui saluran darurat untuk verifikasi keselamatan\n- Siapkan kontak layanan krisis setempat\n- Pantau frekuensi dan urgensi pernyataan berikutnya\n- Pertahankan monitoring rutin','pending','konseling','urgent','2_weeks','2026-08-13 07:00:00.000',NULL,NULL),(16,'2026-08-13 15:10:27.048','2026-08-13 15:10:27.048',NULL,16,29,'TINDAK LANJUT CURHAT AI (Tinggi)\nUser menyatakan keinginan bunuh diri secara eksplisit, dengan riwayat pernyataan serupa sebelumnya.\n\nSinyal terdeteksi:\n- Pernyataan eksplisit \'aku pengen bundir\'\n- Riwayat pernyataan bunuh diri berulang\n- Pernyataan \'beneran\' sebelumnya menegaskan keseriusan\n\nRencana tindakan:\n- Hubungi user melalui saluran darurat untuk verifikasi keselamatan\n- Siapkan kontak layanan krisis setempat\n- Pantau frekuensi dan urgensi pernyataan berikutnya\n- Pertahankan monitoring rutin','pending','konseling','urgent','2_weeks',NULL,NULL,NULL),(17,'2026-08-13 15:11:38.667','2026-08-13 15:20:04.508',NULL,2,27,'PROGRAM PREVENTIF: 1) Lanjutkan pemantauan harian. 2) Pertahankan rutinitas sehat. 3) Latihan napas 5 menit/hari. 4) Tetap terhubung dengan teman/keluarga. 5) Gunakan asesmen sebagai baseline.','completed','konseling','medium','1_week',NULL,NULL,NULL),(18,'2026-08-13 15:18:51.375','2026-08-13 15:18:51.375',NULL,16,29,'TINDAK LANJUT CURHAT AI (Rendah)\nUser berulang kali menyebut \'bundir\' dengan nada iseng, perlu klarifikasi keseriusan.\n\nSinyal terdeteksi:\n- Ucapan \'bundir\' diulang dalam beberapa pesan\n- Nada bercanda tetapi topik sensitif\n\nRencana tindakan:\n- Tanyakan langsung keseriusan niat user\n- Berikan edukasi singkat tentang tanda bahaya bunuh diri\n- Pantau frekuensi topik ini di sesi berikutnya\n- Pertahankan monitoring rutin','pending','konseling','low','2_weeks','2026-08-13 07:00:00.000',NULL,NULL);
